//! `cargo xtask docs`: renders `docs/reference/commands.md` from the command registry.

use std::fmt::Write as _;
use std::fs;
use std::path::PathBuf;

use kraken_registry::{CommandKind, Entry, Permission, Registry};
use serde_json::Value;

use crate::{Result, workspace_root};

const HEADER: &str = "# Command reference

<!-- Generated by `cargo xtask docs` from the command registry. Do not edit by hand. -->

Every command works the same way on every surface. On the command line it is a subcommand
(`snake_case` names become `kebab-case`); in an MCP client it is a tool with the snake_case name.
Arguments marked *required* must be given. Addresses are `0x`-prefixed hex strings. Objects and
arrays are passed to the command line as JSON text.

Permission classes: **safe** commands only read; **mutating** commands change the project and are
logged; **dangerous** commands always ask for approval first.
";

/// Path of the committed reference page.
pub fn reference_path() -> PathBuf {
    workspace_root().join("docs/reference/commands.md")
}

pub fn write_docs() -> Result<()> {
    let path = reference_path();
    if let Some(dir) = path.parent() {
        fs::create_dir_all(dir).map_err(|e| format!("cannot create {}: {e}", dir.display()))?;
    }
    fs::write(&path, render(&Registry::standard()))
        .map_err(|e| format!("cannot write {}: {e}", path.display()))?;
    println!("docs: {}", path.display());
    crate::gui_docs::write_page()
}

fn kind_name(k: CommandKind) -> &'static str {
    match k {
        CommandKind::Query => "query",
        CommandKind::Mutation => "mutation",
        CommandKind::Job => "job",
        CommandKind::Stream => "stream",
    }
}

fn permission_name(p: Permission) -> &'static str {
    match p {
        Permission::Safe => "safe",
        Permission::Mutating => "mutating",
        Permission::Dangerous => "dangerous",
    }
}

/// Renders the whole reference page.
pub fn render(registry: &Registry) -> String {
    let mut out = String::from(HEADER);
    out.push_str("\n| Command | Kind | Permission | Summary |\n|---|---|---|---|\n");
    for e in registry.iter() {
        let s = e.spec();
        let _ = writeln!(
            out,
            "| [`{}`](#{}) | {} | {} | {} |",
            s.name,
            s.name,
            kind_name(s.kind),
            permission_name(s.permission),
            cell(&s.summary)
        );
    }
    for e in registry.iter() {
        render_entry(&mut out, e);
    }
    out
}

/// The command's short doc, with its `Example:` line set apart as a code span.
fn render_doc(doc: &str) -> String {
    doc.trim()
        .lines()
        .map(|l| match l.strip_prefix("Example: ") {
            Some(call) => format!("\nExample: `{call}`"),
            None => l.to_string(),
        })
        .collect::<Vec<_>>()
        .join("\n")
}

fn cell(text: &str) -> String {
    text.replace('|', "\\|").replace('\n', " ")
}

/// One argument property of a command.
struct Arg {
    prop: String,
    flag: String,
    ty: String,
    required: bool,
    description: String,
}

fn render_entry(out: &mut String, e: &Entry) {
    let s = e.spec();
    let cli_name = s.name.replace('_', "-");
    let args_schema = kraken_proto::canonical_json(e.args_schema().clone());
    let args = args_of(&args_schema);
    let _ = write!(out, "\n## {}\n\n", s.name);
    let _ = writeln!(out, "{}\n", s.summary);
    let mut form = format!("kraken {cli_name}");
    for a in args.iter().filter(|a| a.required) {
        let _ = write!(form, " --{} <{}>", a.flag, a.ty);
    }
    if args.iter().any(|a| !a.required) {
        form.push_str(" [options]");
    }
    let _ = writeln!(out, "```sh\n{form}\n```\n");
    let _ = writeln!(
        out,
        "- Kind: {}\n- Permission: {}",
        kind_name(s.kind),
        permission_name(s.permission)
    );
    if !s.needs.is_empty() {
        let needs: Vec<String> = s.needs.iter().map(|c| format!("`{c:?}`")).collect();
        let _ = writeln!(out, "- Engine needs: {}", needs.join(", "));
    }
    out.push('\n');
    if !s.doc.trim().is_empty() {
        let _ = writeln!(out, "{}\n", render_doc(&s.doc));
    }
    if !s.details.trim().is_empty() {
        let _ = writeln!(out, "{}\n", s.details.trim());
    }
    if args.is_empty() {
        out.push_str("Arguments: none.\n\n");
    } else {
        out.push_str(
            "| Argument | CLI flag | Type | Required | Description |\n|---|---|---|---|---|\n",
        );
        for a in &args {
            let _ = writeln!(
                out,
                "| `{}` | `--{}` | {} | {} | {} |",
                a.prop,
                a.flag,
                cell(&a.ty),
                if a.required { "yes" } else { "no" },
                cell(&a.description)
            );
        }
        out.push('\n');
    }
    let pretty =
        serde_json::to_string_pretty(&kraken_proto::canonical_json(e.output_schema().clone()))
            .unwrap_or_default();
    let _ = write!(
        out,
        "<details>\n<summary>Output schema</summary>\n\n```json\n{pretty}\n```\n\n</details>\n"
    );
}

fn args_of(schema: &Value) -> Vec<Arg> {
    let Some(props) = schema.get("properties").and_then(Value::as_object) else {
        return Vec::new();
    };
    let required: Vec<&str> = schema
        .get("required")
        .and_then(Value::as_array)
        .map(|r| r.iter().filter_map(Value::as_str).collect())
        .unwrap_or_default();
    let mut args: Vec<Arg> = props
        .iter()
        .map(|(name, node)| Arg {
            prop: name.clone(),
            flag: name.replace('_', "-"),
            ty: type_of(schema, node),
            required: required.contains(&name.as_str()),
            description: node
                .get("description")
                .and_then(Value::as_str)
                .or_else(|| {
                    resolve(schema, node)
                        .get("description")
                        .and_then(Value::as_str)
                })
                .unwrap_or("")
                .to_string(),
        })
        .collect();
    // Required first, then by name, so the usage line and table read naturally.
    args.sort_by(|a, b| {
        b.required
            .cmp(&a.required)
            .then_with(|| a.prop.cmp(&b.prop))
    });
    args
}

/// Follows a local `$ref` into `$defs`.
fn resolve<'a>(root: &'a Value, node: &'a Value) -> &'a Value {
    let mut cur = node;
    for _ in 0..8 {
        let Some(target) = cur.get("$ref").and_then(Value::as_str) else {
            break;
        };
        let Some(name) = target.strip_prefix("#/$defs/") else {
            break;
        };
        match root.get("$defs").and_then(|d| d.get(name)) {
            Some(next) => cur = next,
            None => break,
        }
    }
    cur
}

fn type_of(root: &Value, node: &Value) -> String {
    if node.get("$ref").and_then(Value::as_str) == Some("#/$defs/Hex64") {
        return "address".into();
    }
    let n = resolve(root, node);
    if let Some(values) = n.get("enum").and_then(Value::as_array) {
        return enum_values(values.iter().filter_map(Value::as_str));
    }
    if let Some(alts) = n
        .get("oneOf")
        .or_else(|| n.get("anyOf"))
        .and_then(Value::as_array)
    {
        let consts: Vec<&str> = alts
            .iter()
            .filter_map(|a| a.get("const").and_then(Value::as_str))
            .collect();
        if !consts.is_empty() && consts.len() == alts.len() {
            return enum_values(consts.into_iter());
        }
        return "json".into();
    }
    match n.get("type") {
        Some(Value::String(t)) => scalar(t),
        Some(Value::Array(ts)) => {
            let names: Vec<&str> = ts
                .iter()
                .filter_map(Value::as_str)
                .filter(|t| *t != "null")
                .collect();
            match names.as_slice() {
                [one] => scalar(one),
                _ => "json".into(),
            }
        }
        _ => "json".into(),
    }
}

fn scalar(t: &str) -> String {
    match t {
        "string" => "string",
        "integer" => "integer",
        "number" => "number",
        "boolean" => "boolean",
        _ => "json",
    }
    .into()
}

fn enum_values<'a>(values: impl Iterator<Item = &'a str>) -> String {
    let v: Vec<String> = values.map(|v| format!("`{v}`")).collect();
    format!("one of {}", v.join(", "))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn committed_reference_is_up_to_date() {
        let path = reference_path();
        let committed = fs::read_to_string(&path).unwrap_or_default();
        assert!(
            committed == render(&Registry::standard()),
            "{} is stale: run `cargo xtask docs` and commit the result",
            path.display()
        );
    }

    #[test]
    fn every_command_is_rendered() {
        let registry = Registry::standard();
        let text = render(&registry);
        for e in registry.iter() {
            assert!(text.contains(&format!("\n## {}\n", e.spec().name)));
        }
    }
}
